{"command":"export UV_CACHE_DIR=/tmp/uv-cache; export TMPDIR=/tmp; uv run python - <<'PY'
from decimal import Decimal
from anamnesis.core.catalogue import load_catalogue
from anamnesis.core.reconcile import reconcile_pair, reconcile_all
from anamnesis.schema import PatientClaim, PackObservation, Strength, IngredientAmount
cat=load_catalogue()
def C(name, s=None, intake=None, status="active", inn=None):
    return PatientClaim(claim_id="c1", name_text=name, inn=inn, strength=s, intake_amount=intake, status=status, audio_evidence=["t1"])
def P(label, s=None, readability="readable"):
    return PackObservation(observation_id="o1", label_text=label, strength=s, readability=readability, visual_evidence=["r1"])
def S(*pairs, per="tablet", unit="mg"):
    return Strength(ingredients=[IngredientAmount(inn=i, amount=Decimal(str(a)), unit=unit) for i,a in pairs], per=per)
def A(inn, v, u="mg"):
    return IngredientAmount(inn=inn, amount=Decimal(str(v)), unit=u)
print("rule7 no-strength:", reconcile_pair(C("Concor"), P("Concor 5 mg"), cat).type)
print("rule7 claim-strength-only:", reconcile_pair(C("Concor", s=S(("bisoprolol",5))), P("Concor 5 mg"), cat).type)
print("capsule half:", reconcile_pair(C("metoprolol", intake=A("metoprolol",50)), P("Beloc-Zok 100 mg", s=S(("metoprolol",100), per="capsule")), cat).type)
print("strength keys differ:", reconcile_pair(C("Panadol", s=S(("paracetamol",500))), P("Panadol Extra", s=S(("paracetamol",500),("caffeine",65))), cat).type)
p2=PackObservation(observation_id="o1", label_text="Panadol Extra", inn="paracetamol", strength=S(("paracetamol",500),("caffeine",65)), readability="readable", visual_evidence=["r1"])
print("pack inn hides combo:", reconcile_pair(C("Panadol", s=S(("paracetamol",500))), p2, cat).type)
print("dup inn:", reconcile_pair(C("Panadol", s=Strength(ingredients=[A("paracetamol",500),A("paracetamol",500)], per="tablet")), P("Panadol", s=S(("paracetamol",500))), cat).type)
print("hyphen space:", cat.resolve("Beloc Zok 100 mg"))
s=cat.resolve("I take Concor and Panadol Extra daily")
print("sentence:", s.brand if s else None)
print("salt:", cat.resolve("metoprolol succinate 100 mg"))
print("ws inn:", reconcile_pair(C("x", inn=" bisoprolol"), P("Concor 5 mg", s=S(("bisoprolol",5))), cat).type)
c1=C("Panadol"); c1.claim_id="c1"; c2=C("Panadol Extra"); c2.claim_id="c2"
o1=P("Panadol Extra", s=S(("paracetamol",500),("caffeine",65))); o1.observation_id="o1"
o2=P("Panadol", s=S(("paracetamol",500))); o2.observation_id="o2"
for f in reconcile_all([c1,c2],[o1,o2],cat):
    print("pair", f.claim_id, f.observation_id, f.type)
from anamnesis.core.guardrails import assert_no_advice, AdviceLeak
for t in ["Continue your tablets", "Split the tablet and take half", "It is safe to double", "Half a tablet is fine", "Keep taking Concor"]:
    try:
        assert_no_advice(t); print("MISS:", t)
    except AdviceLeak: print("caught:", t)
print("per dose vs tablet:", reconcile_pair(C("Concor", s=S(("bisoprolol",5), per="dose")), P("Concor 5 mg", s=S(("bisoprolol",5), per="tablet")), cat).type)
